# -*- coding: utf-8 -*-
"""MANAPRINT — ROMA · 6 BOULES (création 2KEA) · maquette CANVA de Maeva (26/11/2026,
« roma_canva_12_A4 »). Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE
(3 colonnes x 4 rangées), traits de coupe en pointillés. Chaque billet : le Colisée, les
cyprès, les lauriers, les six ronds, la plaque SPQR, la bordure, « 2Kea&Associé » (dessin de
la maquette, posé en pochoir : en couleur, MANAPRINT le repeint, les chiffres restent noirs),
le titre ROMA et la case du n° de série. Le dessin est rangé une seule fois par document.
RÈGLE (inchangée, sceau Maeva 19/09) — 6 NOMBRES PAIRS, une plage par rond :
   rond 1 : 2-14 · rond 2 : 16-30 · rond 3 : 32-44 · rond 4 : 46-60 · rond 5 : 62-74 · rond 6 : 76-90
   -> crieur : les 45 pairs de 2 à 90. Chiffres de la maquette (serif, 30 pt), noirs.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Times-Roman", 30
PLAGES = [(2, 14), (16, 30), (32, 44), (46, 60), (62, 74), (76, 90)]
_XC = [34.44642, 76.36024, 118.0332, 161.1514, 203.547, 245.22]   # centres des six ronds
_YB = 44.00206                                                      # ligne de base des chiffres
# les 3 bandes du dessin : (y, hauteur) dans le billet
_BANDES = [(74.37721, 71.60704), (33.42692, 40.95029), (2.834646, 30.59227)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = tuple(rng.choice(range(a, b + 1, 2)) for a, b in PLAGES)
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False, esp=0):
    w = c.stringWidth(s, police, taille) + esp * max(0, len(s) - 1)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    if esp:
        t.setCharSpace(esp)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_roma_modele", False):
        return
    import base64
    d = _DESSIN.replace("{H}", c._doc.getInternalFontName("Helvetica"))
    c.beginForm("ROMA_CANVA", 0, 0, CELL_W, CELL_H)
    for i, (y, h) in enumerate(_BANDES):
        _masque.poser(c, "ROMA_IMG_%d" % i, base64.b64decode(_PNG[i]), 0, y, CELL_W, h)
    c._code.append("q\n" + d + "\nQ")
    c.endForm()
    c._roma_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("ROMA_CANVA")
    _txt(c, "%05d" % (serie % 100000), 18.42552, 137.2068, "Helvetica", 6.5, NOIR, esp=0.3)
    for x, n in zip(_XC, nums):
        _txt(c, str(n), x, _YB, POLICE_NUM, T_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("ROMA · 6 boules")
    rng = random.Random(int(serie_start) * 100003 + 1909)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


_DESSIN = '0 0 0 RG\n1 1 1 rg\n.5 w\nn\n16.52246 136.9009 m\n39.60353 136.9009 l\n41.01382 136.9009 42.15471 138.0418 42.15471 139.4521 c\n42.15471 139.497 l\n42.15471 140.9072 41.01382 142.0481 39.60353 142.0481 c\n16.52246 142.0481 l\n15.11216 142.0481 13.97128 140.9072 13.97128 139.497 c\n13.97128 139.4521 l\n13.97128 138.0418 15.11216 136.9009 16.52246 136.9009 c\nh\nB*\nBT 1 0 0 1 0 0 Tm 1.2 Tc 1 0 0 1 137.4542 117.8259 Tm 0 0 0 rg /{H} 26 Tf 31.2 TL (ROMA) Tj 0 Tc ET'
_PNG = ['', '', '']


if __name__ == "__main__":
    open("test_roma.pdf", "wb").write(generer_pdf(nb_cartes=12, couleur=False).read())
    print("ROMA genere")
